#!/usr/bin/env python3
"""Generate a C byte array for display attribution (obfuscation, not encryption)."""
from pathlib import Path
import os
NAME = "[المطور: عبدالله لازم]"
MASK = 0x5A
root = Path(__file__).resolve().parents[1]
values = [b ^ MASK for b in NAME.encode("utf-8")]
text = ", ".join(f"0x{x:02x}" for x in values)
output = Path(os.environ.get("ISOX_WATERMARK_OUTPUT", root / "kernel/isox-watermark/watermark_bytes.h"))
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(
    "/* Generated by scripts/encode-watermark.py; XOR-obfuscated UTF-8. */\n"
    f"static const unsigned char isox_watermark_text[] = {{{text}}};\n",
    encoding="utf-8")
print("Generated watermark_bytes.h (obfuscation only; not cryptographic protection).")
